function nextProductId(existingIds) {
  let max = 0;
  for (const raw of existingIds ?? []) {
    const m = String(raw ?? "").trim().match(/^OT-(\d+)$/i);
    if (m) max = Math.max(max, Number.parseInt(m[1], 10));
